"""specs_s200051.py - Sonnet-w2 family D2 (generated by mkfamD2.py): 0x45c4f0 returns a random heap object or 0; INIT records the SEH chain; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _mk(init):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x60), rnd(c, 0x60), rnd(c, 0x60)])
        hook_rec(c, 0x45c4f0, 2, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, init, 3, ret=r.getrandbits(32), pop=12, this=True, side=seh_record(c, 2))
        return [r.getrandbits(32), r.getrandbits(32), r.getrandbits(32), r.getrandbits(32)]
    return gen


S(0x449ca0, 'GUESS famD2 0x449ca0', 'fastcall', None, ret='eax', gen=_mk(0x45c3a0), note='batch200051')
S(0x5d87a0, 'GUESS famD2 0x5d87a0', 'fastcall', None, ret='eax', gen=_mk(0x43de40), note='batch200051')
